package org.jsoup.safety;

/*
    Thank you to Ryan Grove (wonko.com) for the Ruby HTML cleaner http://github.com/rgrove/sanitize/, which inspired
    this safe-list configuration, and the initial defaults.
 */

import org.jsoup.helper.Validate;
import org.jsoup.internal.Normalizer;

import java.util.Objects;

/**
 Safelists define what HTML (elements and attributes) to allow through a {@link Cleaner}. Everything else is removed.
 <p>
 Start with one of the defaults:
 </p>
 <ul>
 <li>{@link #none}
 <li>{@link #simpleText}
 <li>{@link #basic}
 <li>{@link #basicWithImages}
 <li>{@link #relaxed}
 </ul>
 <p>
 If you need to allow more through (please be careful!), tweak a base safelist with its configuration.
 </p>

 <p>
 The {@link Cleaner} and these safelists assume that you want to clean a <code>body</code> fragment of HTML (to add user
 supplied HTML into a templated page), and not to clean a full HTML document. If the latter is the case, you could wrap
 the templated document HTML around the cleaned body HTML.
 </p>
 <p>
 Safelists are mutable. A {@link Cleaner} uses the supplied safelist directly, so later changes affect later cleaning
 calls. If you want to share a safelist across threads, finish configuring it first and do not mutate it while it is in
 use. To build a variant from an existing configuration, use {@link #Safelist(Safelist)} to make a copy.
 </p>
 <p>
 If you are going to extend a safelist, please be very careful. Make sure you understand what attributes may lead to
 XSS attack vectors. URL attributes are particularly vulnerable and require careful validation. See 
 the <a href="https://owasp.org/www-community/xss-filter-evasion-cheatsheet">XSS Filter Evasion Cheat Sheet</a> for some
 XSS attack examples (that jsoup will safeguard against with the default Cleaner and Safelist configuration).
 </p>
 */
public class Safelist {
    private final SafelistConfig config;

    /**
     This safelist allows only text nodes: any HTML Element or any Node other than a TextNode will be removed.
     <p>
     Note that the output of {@link org.jsoup.Jsoup#clean(String, Safelist)} is still <b>HTML</b> even when using
     this Safelist, and so any HTML entities in the output will be appropriately escaped. If you want plain text, not
     HTML, you should use a text method such as {@link org.jsoup.nodes.Element#text()} instead, after cleaning the document.
     </p>
     <p>Example:</p>
     <pre>{@code
     String sourceBodyHtml = "<p>5 is &lt; 6.</p>";
     String html = Jsoup.clean(sourceBodyHtml, Safelist.none());

     Cleaner cleaner = new Cleaner(Safelist.none());
     String text = cleaner.clean(Jsoup.parse(sourceBodyHtml)).text();

     // html is: 5 is &lt; 6.
     // text is: 5 is < 6.
     }</pre>

     @return safelist
     */
    public static Safelist none() {
        return new Safelist();
    }

    /**
     This safelist allows only simple text formatting: <code>b, em, i, strong, u</code>. All other HTML (tags and
     attributes) will be removed.

     @return safelist
     */
    public static Safelist simpleText() {
        Safelist s = new Safelist();
        s.config.addTags("b", "em", "i", "strong", "u");
        return s;
    }

    /**
     <p>
     This safelist allows a fuller range of text nodes: <code>a, b, blockquote, br, cite, code, dd, dl, dt, em, i, li,
     ol, p, pre, q, small, span, strike, strong, sub, sup, u, ul</code>, and appropriate attributes.
     </p>
     <p>
     Links (<code>a</code> elements) can point to <code>http, https, ftp, mailto</code>, and have an enforced
     <code>rel=nofollow</code> attribute if they link offsite (as indicated by the specified base URI).
     </p>
     <p>
     Does not allow images.
     </p>

     @return safelist
     */
    public static Safelist basic() {
        Safelist s = new Safelist();
        s.config.addTags(
            "a", "b", "blockquote", "br", "cite", "code", "dd", "dl", "dt", "em",
            "i", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong", "sub",
            "sup", "u", "ul");

        s.config.addAttributes("a", "href");
        s.config.addAttributes("blockquote", "cite");
        s.config.addAttributes("q", "cite");

        s.config.addProtocols("a", "href", "ftp", "http", "https", "mailto");
        s.config.addProtocols("blockquote", "cite", "http", "https");
        s.config.addProtocols("cite", "cite", "http", "https");

        s.config.addEnforcedAttribute("a", "rel", "nofollow");
        return s;
    }

    /**
     This safelist allows the same text tags as {@link #basic}, and also allows <code>img</code> tags, with appropriate
     attributes, with <code>src</code> pointing to <code>http</code> or <code>https</code>.

     @return safelist
     */
    public static Safelist basicWithImages() {
        Safelist s = basic();
        s.config.addTags("img");
        s.config.addAttributes("img", "align", "alt", "height", "src", "title", "width");
        s.config.addProtocols("img", "src", "http", "https");
        return s;
    }

    /**
     This safelist allows a full range of text and structural body HTML: <code>a, b, blockquote, br, caption, cite,
     code, col, colgroup, dd, div, dl, dt, em, h1, h2, h3, h4, h5, h6, i, img, li, ol, p, pre, q, small, span, strike, strong, sub,
     sup, table, tbody, td, tfoot, th, thead, tr, u, ul</code>
     <p>
     Links do not have an enforced <code>rel=nofollow</code> attribute, but you can add that if desired.
     </p>

     @return safelist
     */
    public static Safelist relaxed() {
        Safelist s = new Safelist();
        s.config.addTags(
            "a", "b", "blockquote", "br", "caption", "cite", "code", "col",
            "colgroup", "dd", "div", "dl", "dt", "em", "h1", "h2", "h3", "h4", "h5", "h6",
            "i", "img", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong",
            "sub", "sup", "table", "tbody", "td", "tfoot", "th", "thead", "tr", "u",
            "ul");

        s.config.addAttributes("a", "href", "title");
        s.config.addAttributes("blockquote", "cite");
        s.config.addAttributes("col", "span", "width");
        s.config.addAttributes("colgroup", "span", "width");
        s.config.addAttributes("img", "align", "alt", "height", "src", "title", "width");
        s.config.addAttributes("ol", "start", "type");
        s.config.addAttributes("q", "cite");
        s.config.addAttributes("table", "summary", "width");
        s.config.addAttributes("td", "abbr", "axis", "colspan", "rowspan", "width");
        s.config.addAttributes("th", "abbr", "axis", "colspan", "rowspan", "scope", "width");
        s.config.addAttributes("ul", "type");

        s.config.addProtocols("a", "href", "ftp", "http", "https", "mailto");
        s.config.addProtocols("blockquote", "cite", "http", "https");
        s.config.addProtocols("cite", "cite", "http", "https");
        s.config.addProtocols("img", "src", "http", "https");
        s.config.addProtocols("q", "cite", "http", "https");
        return s;
    }

    /**
     Create a new, empty safelist. Generally it will be better to start with a default prepared safelist instead.

     @see #basic()
     @see #basicWithImages()
     @see #simpleText()
     @see #relaxed()
     */
    public Safelist() {
        config = new SafelistConfig();
    }

    /**
     Deep copy an existing Safelist to a new Safelist.
     @param copy the Safelist to copy
     */
    public Safelist(Safelist copy) {
        Validate.notNull(copy);
        config = new SafelistConfig(copy.config);
    }

    public SafelistConfig config() {
        return config;
    }

    boolean isSafeTag(String tag) {
        return config.isSafeTag(tag);
    }

    boolean isSafeAttribute(String tagName, org.jsoup.nodes.Element el, org.jsoup.nodes.Attribute attr) {
        return config.isSafeAttribute(tagName, el, attr);
    }

    org.jsoup.nodes.Attributes getEnforcedAttributes(String tagName) {
        return config.getEnforcedAttributes(tagName);
    }

    boolean shouldAbsUrl(String tagName, String attrKey) {
        return config.shouldAbsUrl(tagName, attrKey);
    }

    // named types for config. All just hold strings, but here for my sanity.

    static class TagName extends TypedValue {
        TagName(String value) {
            super(value);
        }

        static TagName valueOf(String value) {
            return new TagName(Normalizer.lowerCase(value));
        }
    }

    static class AttributeKey extends TypedValue {
        AttributeKey(String value) {
            super(value);
        }

        static AttributeKey valueOf(String value) {
            return new AttributeKey(Normalizer.lowerCase(value));
        }
    }

    static class AttributeValue extends TypedValue {
        AttributeValue(String value) {
            super(value);
        }

        static AttributeValue valueOf(String value) {
            return new AttributeValue(value);
        }
    }

    static class Protocol extends TypedValue {
        Protocol(String value) {
            super(value);
        }

        static Protocol valueOf(String value) {
            return new Protocol(value);
        }
    }

    abstract static class TypedValue {
        private final String value;

        TypedValue(String value) {
            Validate.notNull(value);
            this.value = value;
        }

        @Override
        public int hashCode() {
            return value.hashCode();
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            TypedValue other = (TypedValue) obj;
            return Objects.equals(value, other.value);
        }

        @Override
        public String toString() {
            return value;
        }
    }
}

package org.jsoup.safety;

import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;

import static org.jsoup.internal.Normalizer.lowerCase;

public class SafelistConfig {
    private static final String All = ":all";
    private static final Safelist.TagName AllTag = Safelist.TagName.valueOf(All);

    private final Set<Safelist.TagName> tagNames;
    private final Map<Safelist.TagName, Set<Safelist.AttributeKey>> attributes;
    private final Map<Safelist.TagName, Map<Safelist.AttributeKey, Safelist.AttributeValue>> enforcedAttributes;
    private final Map<Safelist.TagName, Map<Safelist.AttributeKey, Set<Safelist.Protocol>>> protocols;
    private boolean preserveRelativeLinks;

    public SafelistConfig() {
        tagNames = new HashSet<>();
        attributes = new HashMap<>();
        enforcedAttributes = new HashMap<>();
        protocols = new HashMap<>();
        preserveRelativeLinks = false;
    }

    public SafelistConfig(SafelistConfig copy) {
        this();
        tagNames.addAll(copy.tagNames);
        for (Map.Entry<Safelist.TagName, Set<Safelist.AttributeKey>> copyTagAttributes : copy.attributes.entrySet()) {
            attributes.put(copyTagAttributes.getKey(), new HashSet<>(copyTagAttributes.getValue()));
        }
        for (Map.Entry<Safelist.TagName, Map<Safelist.AttributeKey, Safelist.AttributeValue>> enforcedEntry : copy.enforcedAttributes.entrySet()) {
            enforcedAttributes.put(enforcedEntry.getKey(), new HashMap<>(enforcedEntry.getValue()));
        }
        for (Map.Entry<Safelist.TagName, Map<Safelist.AttributeKey, Set<Safelist.Protocol>>> protocolsEntry : copy.protocols.entrySet()) {
            Map<Safelist.AttributeKey, Set<Safelist.Protocol>> attributeProtocolsCopy = new HashMap<>();
            for (Map.Entry<Safelist.AttributeKey, Set<Safelist.Protocol>> attributeProtocols : protocolsEntry.getValue().entrySet()) {
                attributeProtocolsCopy.put(attributeProtocols.getKey(), new HashSet<>(attributeProtocols.getValue()));
            }
            protocols.put(protocolsEntry.getKey(), attributeProtocolsCopy);
        }
        preserveRelativeLinks = copy.preserveRelativeLinks;
    }

    public SafelistConfig addTags(String... tags) {
        Validate.notNull(tags);

        for (String tagName : tags) {
            Validate.notEmpty(tagName);
            Validate.isFalse(tagName.equalsIgnoreCase("noscript"),
                "noscript is unsupported in Safelists, due to incompatibilities between parsers with and without script-mode enabled");
            tagNames.add(Safelist.TagName.valueOf(tagName));
        }
        return this;
    }

    public SafelistConfig removeTags(String... tags) {
        Validate.notNull(tags);

        for (String tag : tags) {
            Validate.notEmpty(tag);
            Safelist.TagName tagName = Safelist.TagName.valueOf(tag);

            if (tagNames.remove(tagName)) {
                attributes.remove(tagName);
                enforcedAttributes.remove(tagName);
                protocols.remove(tagName);
            }
        }
        return this;
    }

    public SafelistConfig addAttributes(String tag, String... attributes) {
        Validate.notEmpty(tag);
        Validate.notNull(attributes);
        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");

        addTags(tag);
        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        Set<Safelist.AttributeKey> attributeSet = new HashSet<>();
        for (String key : attributes) {
            Validate.notEmpty(key);
            attributeSet.add(Safelist.AttributeKey.valueOf(key));
        }
        Set<Safelist.AttributeKey> currentSet = this.attributes.computeIfAbsent(tagName, k -> new HashSet<>());
        currentSet.addAll(attributeSet);
        return this;
    }

    public SafelistConfig removeAttributes(String tag, String... attributes) {
        Validate.notEmpty(tag);
        Validate.notNull(attributes);
        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");

        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        Set<Safelist.AttributeKey> attributeSet = new HashSet<>();
        for (String key : attributes) {
            Validate.notEmpty(key);
            attributeSet.add(Safelist.AttributeKey.valueOf(key));
        }
        if (tagNames.contains(tagName) && this.attributes.containsKey(tagName)) {
            Set<Safelist.AttributeKey> currentSet = this.attributes.get(tagName);
            currentSet.removeAll(attributeSet);

            if (currentSet.isEmpty())
                this.attributes.remove(tagName);
        }
        if (tag.equals(All)) {
            Iterator<Map.Entry<Safelist.TagName, Set<Safelist.AttributeKey>>> it = this.attributes.entrySet().iterator();
            while (it.hasNext()) {
                Map.Entry<Safelist.TagName, Set<Safelist.AttributeKey>> entry = it.next();
                Set<Safelist.AttributeKey> currentSet = entry.getValue();
                currentSet.removeAll(attributeSet);
                if (currentSet.isEmpty())
                    it.remove();
            }
        }
        return this;
    }

    public SafelistConfig addEnforcedAttribute(String tag, String attribute, String value) {
        Validate.notEmpty(tag);
        Validate.notEmpty(attribute);
        Validate.notEmpty(value);

        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        tagNames.add(tagName);
        Safelist.AttributeKey attrKey = Safelist.AttributeKey.valueOf(attribute);
        Safelist.AttributeValue attrVal = Safelist.AttributeValue.valueOf(value);

        Map<Safelist.AttributeKey, Safelist.AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
        attrMap.put(attrKey, attrVal);
        return this;
    }

    public SafelistConfig removeEnforcedAttribute(String tag, String attribute) {
        Validate.notEmpty(tag);
        Validate.notEmpty(attribute);

        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        if (tagNames.contains(tagName) && enforcedAttributes.containsKey(tagName)) {
            Safelist.AttributeKey attrKey = Safelist.AttributeKey.valueOf(attribute);
            Map<Safelist.AttributeKey, Safelist.AttributeValue> attrMap = enforcedAttributes.get(tagName);
            attrMap.remove(attrKey);

            if (attrMap.isEmpty())
                enforcedAttributes.remove(tagName);
        }
        return this;
    }

    public SafelistConfig preserveRelativeLinks(boolean preserve) {
        preserveRelativeLinks = preserve;
        return this;
    }

    public boolean preserveRelativeLinks() {
        return preserveRelativeLinks;
    }

    public SafelistConfig addProtocols(String tag, String attribute, String... protocols) {
        Validate.notEmpty(tag);
        Validate.notEmpty(attribute);
        Validate.notNull(protocols);

        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        Safelist.AttributeKey attrKey = Safelist.AttributeKey.valueOf(attribute);
        Map<Safelist.AttributeKey, Set<Safelist.Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
        Set<Safelist.Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());

        for (String protocol : protocols) {
            Validate.notEmpty(protocol);
            Safelist.Protocol prot = Safelist.Protocol.valueOf(protocol);
            protSet.add(prot);
        }
        return this;
    }

    public SafelistConfig removeProtocols(String tag, String attribute, String... removeProtocols) {
        Validate.notEmpty(tag);
        Validate.notEmpty(attribute);
        Validate.notNull(removeProtocols);

        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        Safelist.AttributeKey attr = Safelist.AttributeKey.valueOf(attribute);

        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
        Map<Safelist.AttributeKey, Set<Safelist.Protocol>> tagProtocols = protocols.get(tagName);
        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");

        Set<Safelist.Protocol> attrProtocols = tagProtocols.get(attr);
        for (String protocol : removeProtocols) {
            Validate.notEmpty(protocol);
            attrProtocols.remove(Safelist.Protocol.valueOf(protocol));
        }

        if (attrProtocols.isEmpty()) {
            tagProtocols.remove(attr);
            if (tagProtocols.isEmpty())
                protocols.remove(tagName);
        }
        return this;
    }

    public boolean isSafeTag(String tag) {
        return tagNames.contains(Safelist.TagName.valueOf(tag));
    }

    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
        Safelist.TagName tag = Safelist.TagName.valueOf(tagName);
        Safelist.AttributeKey key = Safelist.AttributeKey.valueOf(attr.getKey());

        Set<Safelist.AttributeKey> okSet = attributes.get(tag);
        if (okSet != null && okSet.contains(key)) {
            if (protocols.containsKey(tag)) {
                Map<Safelist.AttributeKey, Set<Safelist.Protocol>> attrProts = protocols.get(tag);
                return !attrProts.containsKey(key) || isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key));
            } else {
                return true;
            }
        }
        Map<Safelist.AttributeKey, Safelist.AttributeValue> enforcedSet = enforcedAttributes.get(tag);
        if (enforcedSet != null && enforcedSet.containsKey(key)) {
            return enforcedSet.get(key).equals(Safelist.AttributeValue.valueOf(attr.getValue()));
        }
        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
    }

    public Attributes getEnforcedAttributes(String tagName) {
        Attributes attrs = new Attributes();
        Safelist.TagName tag = Safelist.TagName.valueOf(tagName);
        if (enforcedAttributes.containsKey(tag)) {
            Map<Safelist.AttributeKey, Safelist.AttributeValue> keyVals = enforcedAttributes.get(tag);
            for (Map.Entry<Safelist.AttributeKey, Safelist.AttributeValue> entry : keyVals.entrySet()) {
                attrs.put(entry.getKey().toString(), entry.getValue().toString());
            }
        }
        return attrs;
    }

    boolean shouldAbsUrl(String tagName, String attrKey) {
        if (preserveRelativeLinks) return false;
        return shouldAbsUrl(Safelist.TagName.valueOf(tagName), Safelist.AttributeKey.valueOf(attrKey));
    }

    private String getProtocolValue(Element el, Attribute attr) {
        String value = el.absUrl(attr.getKey());
        if (value.isEmpty())
            value = attr.getValue();
        return value;
    }

    private boolean isSafeProtocol(String value, Set<Safelist.Protocol> protocols) {
        for (Safelist.Protocol protocol : protocols) {
            String prot = protocol.toString();

            if (prot.equals("#")) {
                if (isValidAnchor(value)) {
                    return true;
                } else {
                    continue;
                }
            }

            prot += ":";

            if (lowerCase(value).startsWith(prot)) {
                return true;
            }
        }
        return false;
    }

    private boolean shouldAbsUrl(Safelist.TagName tag, Safelist.AttributeKey key) {
        Set<Safelist.AttributeKey> allowedAttrs = attributes.get(tag);
        if (allowedAttrs != null && allowedAttrs.contains(key)) {
            Map<Safelist.AttributeKey, Set<Safelist.Protocol>> protocolsByAttr = protocols.get(tag);
            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
        }

        Map<Safelist.AttributeKey, Safelist.AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;

        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
    }

    private static boolean isValidAnchor(String value) {
        return value.startsWith("#") && !value.matches(".*\\s.*");
    }
}

package org.jsoup.integration;

import org.jsoup.Jsoup;
import org.jsoup.TextUtil;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Element;
import org.jsoup.safety.Safelist;
import org.jsoup.safety.SafelistConfig;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 Check that we can extend Safelist methods
 */
public class SafelistExtensionTest {
    @Test public void canCustomizeSafeTests() {
        OpenSafelist openSafelist = new OpenSafelist(Safelist.relaxed());
        Safelist safelist = Safelist.relaxed();

        String html = "<p><opentag openattr>Hello</opentag></p>";

        String openClean = Jsoup.clean(html, openSafelist);
        String clean = Jsoup.clean(html, safelist);

        assertEquals("<p><opentag openattr=\"\">Hello</opentag></p>", TextUtil.stripNewlines(openClean));
        assertEquals("<p>Hello</p>", clean);
    }

    // passes tags and attributes starting with "open"
    private static class OpenSafelist extends Safelist {
        private final OpenSafelistConfig openConfig;

        public OpenSafelist(Safelist safelist) {
            super(safelist);
            openConfig = new OpenSafelistConfig(config());
        }

        @Override
        boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
            return openConfig.isSafeAttribute(tagName, el, attr);
        }

        @Override
        boolean isSafeTag(String tag) {
            return openConfig.isSafeTag(tag);
        }
    }

    private static class OpenSafelistConfig extends SafelistConfig {
        public OpenSafelistConfig(SafelistConfig config) {
            super(config);
        }

        @Override
        public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
            if (attr.getKey().startsWith("open"))
                return true;
            return super.isSafeAttribute(tagName, el, attr);
        }

        @Override
        public boolean isSafeTag(String tag) {
            if (tag.startsWith("open"))
                return true;
            return super.isSafeTag(tag);
        }
    }
}

package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.MultiLocaleExtension.MultiLocaleTest;
import org.jsoup.TextUtil;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Entities;
import org.jsoup.nodes.Range;
import org.jsoup.parser.ParseSettings;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.parser.TagSet;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import java.util.Arrays;
import java.util.Locale;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.jupiter.api.Assertions.*;

/**
 Tests for the cleaner.

 @author Jonathan Hedley, jonathan@hedley.net */
public class CleanerTest {
    @Test public void simpleBehaviourTest() {
        String h = "<div><p class=foo><a href='http://evil.com'>Hello <b id=bar>there</b>!</a></div>";
        String cleanHtml = Jsoup.clean(h, Safelist.simpleText());

        assertEquals("Hello <b>there</b>!", TextUtil.stripNewlines(cleanHtml));
    }

    @Test public void simpleBehaviourTest2() {
        String h = "Hello <b>there</b>!";
        String cleanHtml = Jsoup.clean(h, Safelist.simpleText());

        assertEquals("Hello <b>there</b>!", TextUtil.stripNewlines(cleanHtml));
    }

    @Test public void basicBehaviourTest() {
        String h = "<div><p><a href='javascript:sendAllMoney()'>Dodgy</a> <A HREF='HTTP://nice.com'>Nice</a></p><blockquote>Hello</blockquote>";
        String cleanHtml = Jsoup.clean(h, Safelist.basic());

        assertEquals("<p><a rel=\"nofollow\">Dodgy</a> <a href=\"http://nice.com\" rel=\"nofollow\">Nice</a></p><blockquote>Hello</blockquote>",
                TextUtil.stripNewlines(cleanHtml));
    }

    @Test public void basicWithImagesTest() {
        String h = "<div><p><img src='http://example.com/' alt=Image></p><p><img src='ftp://ftp.example.com'></p></div>";
        String cleanHtml = Jsoup.clean(h, Safelist.basicWithImages());
        assertEquals("<p><img src=\"http://example.com/\" alt=\"Image\"></p><p><img></p>", TextUtil.stripNewlines(cleanHtml));
